mapper.insert:
INSERT INTO production_event (work_order_id, equipment_id, occurred_at, good_qty, bad_qty) SELECT v.work_order_id, v.equipment_id, v.occurred_at, GREATEST(v.good_count - COALESCE(p.good_count, 0), 0), GREATEST(v.bad_count - COALESCE(p.bad_count, 0), 0) FROM (VALUES
( CAST(#{row.workOrderId} AS VARCHAR), CAST(#{row.equipmentId} AS VARCHAR), CAST(#{row.occurredAt} AS TIMESTAMPTZ), CAST(#{row.totalCount} AS INT), CAST(#{row.goodCount} AS INT), CAST(#{row.badCount} AS INT) )
) AS v (work_order_id, equipment_id, occurred_at, total_count, good_count, bad_count) LEFT JOIN production_performance p ON p.work_order_id = v.work_order_id AND p.equipment_id = v.equipment_id WHERE v.total_count > COALESCE(p.total_count, 0)
